{
  "version": 1,
  "factory": {
    "enabled": false,
    "scope": "Implement explicitly authorized managed issues and publish review Draft PRs."
  },
  "manager": {
    "workflow": "factory-manager.yml",
    "maxActions": 10,
    "timeoutMinutes": 15,
    "maxContextTasks": 20,
    "maxContextChars": 20000,
    "trustedActors": [
      "github-actions[bot]"
    ]
  },
  "autonomy": {
    "profile": "autonomous",
    "overrides": {
      "merge_pr": "deny",
      "close_issue": "deny",
      "create_followup": "deny",
      "expand_scope": "deny"
    }
  },
  "execution": {
    "engine": "temporal",
    "dryRun": false,
    "maxParallelWorkers": 1,
    "maxRetries": 2,
    "maxNewIssues": 3,
    "workerTimeoutMinutes": 30,
    "dispatchGraceMinutes": 10,
    "rework": false
  },
  "llm": {
    "provider": "mock",
    "model": "gpt-4.1-mini",
    "reasoningEffort": null,
    "maxOutputTokens": 4000,
    "timeoutSeconds": 60,
    "maxCalls": 1
  },
  "workers": {
    "test": {
      "enabled": false,
      "operation": "sha256"
    },
    "coding": {
      "enabled": true,
      "agent": "codex",
      "model": "gpt-6.1-sol",
      "reasoningEffort": "high",
      "validationWorkflow": null,
      "loopback": false
    },
    "review": false
  },
  "reporting": {
    "persistDecisions": true
  },
  "merge": {
    "enabled": false,
    "includeFactoryPRs": true,
    "adoptLabel": "sf:automerge",
    "method": "squash",
    "updateBranch": true,
    "requiredChecks": [
      "test-backend",
      "test-frontend",
      "test-docker"
    ],
    "validationWorkflow": "test.yml",
    "maxReviewsPerRun": 2,
    "maxActionsPerRun": 1,
    "review": {
      "model": "gpt-6.1-sol",
      "reasoningEffort": "high",
      "timeoutSeconds": 120,
      "maxOutputTokens": 6000,
      "maxFiles": 60,
      "maxContextBytes": 250000
    },
    "postMergeWorkflows": []
  },
  "deploy": {
    "enabled": false,
    "provider": "docker-ssh",
    "trigger": "checks",
    "workflows": [],
    "environment": "production",
    "host": null,
    "port": null,
    "user": null,
    "path": "/opt/app",
    "composeFile": "compose.yaml",
    "project": null,
    "envFile": ".env",
    "healthcheck": {
      "url": null,
      "timeoutSeconds": 180
    },
    "rollback": true,
    "keepReleases": 5,
    "timeoutMinutes": 30,
    "githubDeployment": false
  },
  "notifications": {
    "slack": {
      "enabled": false,
      "channel": null,
      "maxPerRun": 20,
      "since": null,
      "events": {
        "issue_created": {
          "enabled": false,
          "channel": null
        },
        "pr_merged": {
          "enabled": false,
          "channel": null,
          "actors": []
        }
      }
    }
  }
}
